/**
 * TASK: Complete the onSelectionChanged method.
 *
 * The panel has a JList named "items" holding five fruits and a JLabel
 * named "choice". Whenever the list selection changes, the label must
 * show the currently selected value, or "nothing" when the selection
 * is empty.
 *
 * Example: selecting index 2 ("Cherry") sets the label to "Cherry";
 * clearing the selection sets it back to "nothing".
 *
 * The components are already created, named, and wired for you.
 */
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.event.ListSelectionEvent;

public class ListPickerPanel extends JPanel {

    private final JList<String> items = new JList<>(
            new String[] { "Apple", "Banana", "Cherry", "Date", "Elderberry" });
    private final JLabel choice = new JLabel("nothing");

    public ListPickerPanel() {
        items.setName("items");
        choice.setName("choice");
        add(new JScrollPane(items));
        add(choice);
        items.addListSelectionListener(this::onSelectionChanged);
    }

    private void onSelectionChanged(ListSelectionEvent e) {
        // TODO: show the selected value in the choice label ("nothing" if none)
    }
}

