public class ListPickerPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            ListPickerPanel panel = new ListPickerPanel();
            java.awt.Component listComp = find(panel, "items");
            java.awt.Component label = find(panel, "choice");
            check("list named items exists", true, listComp instanceof javax.swing.JList);
            check("initial choice", "nothing", textOf(label));
            if (listComp instanceof javax.swing.JList) {
                javax.swing.JList<?> list = (javax.swing.JList<?>) listComp;
                check("list holds five items", 5, list.getModel().getSize());
                list.setSelectedIndex(2);
                check("after selecting index 2", "Cherry", textOf(label));
                list.setSelectedIndex(0);
                check("after selecting index 0", "Apple", textOf(label));
                list.setSelectedIndex(4);
                check("after selecting index 4", "Elderberry", textOf(label));
                list.clearSelection();
                check("after clearing the selection", "nothing", textOf(label));
            } else {
                failures++;
                System.out.println("FAIL  JList not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

